<?php
declare(strict_types=1);namespace App\Application\Ledger;
use App\Application\{Audit\AuditWriter,Events\OutboxWriter};use App\Models\FinancialPostingProfile;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class FinancialPostingService{public function __construct(private LedgerService$ledger,private AuditWriter$audit,private OutboxWriter$outbox){}public function post(?string$tenant,string$event,string$referenceId,int$amount,string$currency,string$correlation):string{if($amount<=0)throw ValidationException::withMessages(['amount'=>__('wave4.positive_amount')]);if($existing=DB::table('journals')->where(['reference_type'=>$event,'reference_id'=>$referenceId,'status'=>'POSTED'])->value('id'))return$existing;$p=FinancialPostingProfile::where(['event_type'=>$event,'currency'=>$currency,'status'=>'APPROVED'])->where(fn($q)=>$q->where('tenant_id',$tenant)->orWhereNull('tenant_id'))->orderByRaw('tenant_id IS NULL ASC')->first();if(!$p)throw ValidationException::withMessages(['posting_profile'=>__('wave4.posting_profile_missing')]);$id=$this->ledger->post($tenant,$event,$referenceId,$currency,[['account_id'=>$p->debit_account_id,'debit_minor'=>$amount,'credit_minor'=>0],['account_id'=>$p->credit_account_id,'debit_minor'=>0,'credit_minor'=>$amount]],$correlation);$this->audit->record('ledger.event.posted','journal',$id,['event'=>$event,'reference_id'=>$referenceId]);$this->outbox->record('ledger.event.posted','journal',$id,['journal_id'=>$id,'event'=>$event]);return$id;}}
